-- CoinSparkLine private account data + behavioural alert delivery.
create table if not exists public.watchlist_items(user_id uuid references auth.users(id) on delete cascade not null,coin_id text not null,created_at timestamptz default now(),primary key(user_id,coin_id));
create table if not exists public.portfolio_items(id bigint generated by default as identity primary key,user_id uuid references auth.users(id) on delete cascade not null,coin_id text not null,symbol text not null,quantity numeric not null check(quantity>=0),average_cost_usd numeric check(average_cost_usd>=0),created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.alert_rules(id bigint generated by default as identity primary key,user_id uuid references auth.users(id) on delete cascade not null,coin_id text not null,rule_type text not null,rule_value text,enabled boolean default true,created_at timestamptz default now());
alter table public.alert_rules add column if not exists last_triggered_at timestamptz;
alter table public.alert_rules add column if not exists last_fingerprint text;
alter table public.watchlist_items enable row level security;alter table public.portfolio_items enable row level security;alter table public.alert_rules enable row level security;
do $$ begin create policy "own watchlist" on public.watchlist_items for all using((select auth.uid())=user_id) with check((select auth.uid())=user_id); exception when duplicate_object then null; end $$;
do $$ begin create policy "own portfolio" on public.portfolio_items for all using((select auth.uid())=user_id) with check((select auth.uid())=user_id); exception when duplicate_object then null; end $$;
do $$ begin create policy "own alerts" on public.alert_rules for all using((select auth.uid())=user_id) with check((select auth.uid())=user_id); exception when duplicate_object then null; end $$;
create index if not exists watchlist_user_idx on public.watchlist_items(user_id);create index if not exists portfolio_user_idx on public.portfolio_items(user_id);create index if not exists alerts_user_idx on public.alert_rules(user_id);create index if not exists alerts_enabled_idx on public.alert_rules(enabled,coin_id);
